function calculateBargainDropPrice(usdCost) {
  let multiplier;

  if (usdCost < 10) {
    multiplier = 3.2;
  } else if (usdCost <= 15) {
    multiplier = 2.8;
  } else if (usdCost <= 22) {
    multiplier = 2.5;
  } else if (usdCost <= 30) {
    multiplier = 2.2;
  } else if (usdCost <= 60) {
    multiplier = 1.9;
  } else {
    multiplier = 1.7;
  }

  const fxRate = 1.4234;
  const rawPrice = usdCost * multiplier * fxRate;

  // Ceiling the value and adjust to end in .95
  const finalPrice = Math.ceil(rawPrice) - 0.05;

  return {
    price: Number(finalPrice.toFixed(2)),
    compareAtPrice: null,
    appliedMultiplier: multiplier
  };
}

