### Plan:
1. Create a local script (`auto-patcher.js`) that reads a target file in your repo.
2. Sends the file content and your prompt to an LLM API.
3. Automatically writes the returned code back to the file.

### Code to apply (`auto-patcher.js`):

```javascript
const fs = require('fs');
const path = require('path');
// Note: npm install node-fetch or use native fetch in Node 18+

async function runAutoPatcher(targetFilePath, instructions) {
    const apiKey = process.env.AI_API_KEY; // Stored safely in your local environment
    if (!apiKey) {
        console.error("Error: AI_API_KEY environment variable is not set.");
        process.exit(1);
    }

    const fullPath = path.resolve(targetFilePath);
    const fileContent = fs.readFileSync(fullPath, 'utf8');

    console.log(`Reading ${targetFilePath}... Sending to AI engine...`);

    const response = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${apiKey}`
        },
        body: JSON.stringify({
            model: "gpt-4o",
            messages: [
                { role: "system", content: "You are a precise code editor. Return ONLY the updated code block, no markdown formatting, no explanations." },
                { role: "user", content: `Instructions: ${instructions}\n\nExisting Code:\n${fileContent}` }
            ],
            temperature: 0.1
        })
    });

    const data = await response.json();
    const updatedCode = data.choices[0].message.content.trim();

    fs.writeFileSync(fullPath, updatedCode, 'utf8');
    console.log(`Successfully updated ${targetFilePath}! Ready for git commit.`);
}

// Example usage: node auto-patcher.js worker.js "fix the error handling"
const args = process.argv.slice(2);
if (args.length < 2) {
    console.log("Usage: node auto-patcher.js <file-path> <instructions>");
    process.exit(1);
}

runAutoPatcher(args[0], args[1]);
```

### How to use it locally:
1. Save this as `auto-patcher.js` in your project root.
2. Set your API key in your terminal: `export AI_API_KEY="your-api-key-here"`
3. Run it whenever you want to update a file automatically: `node auto-patcher.js worker.js "your update instructions here"`

